export const exercises = [{"id":"Bodyweight_Squat","name":"Bodyweight squat","group":"Home basics","type":"Strength","area":"Legs","muscles":["quadriceps"],"secondary":["glutes","hamstrings"],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.","Begin the movement by flexing your knees and hips, sitting back with your hips.","Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out."],"cues":["Keep your feet planted.","Let knees follow the toes.","Keep the movement controlled."],"images":["assets/exercises/Bodyweight_Squat/0.webp","assets/exercises/Bodyweight_Squat/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Bodyweight_Squat"},{"id":"Pushups","name":"Press-up","group":"Home basics","type":"Strength","area":"Chest","muscles":["chest"],"secondary":["shoulders","triceps"],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.","Next, lower yourself downward until your chest almost touches the floor as you inhale.","Now breathe out and press your upper body back up to the starting position while squeezing your chest.","After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed."],"cues":["Keep wrists aligned with forearms.","Brace your trunk.","Press smoothly; avoid bouncing."],"images":["assets/exercises/Pushups/0.webp","assets/exercises/Pushups/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Pushups"},{"id":"Incline_Push-Up","name":"Incline press-up","group":"Home basics","type":"Strength","area":"Chest","muscles":["chest"],"secondary":["shoulders","triceps"],"equipment":["Bench"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Stand facing bench or sturdy elevated platform. Place hands on edge of bench or platform, slightly wider than shoulder width.","Position forefoot back from bench or platform with arms and body straight. Arms should be perpendicular to body. Keeping body straight, lower chest to edge of box or platform by bending arms.","Push body up until arms are extended. Repeat."],"cues":["Keep wrists aligned with forearms.","Brace your trunk.","Press smoothly; avoid bouncing."],"images":["assets/exercises/Incline_Push-Up/0.webp","assets/exercises/Incline_Push-Up/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Incline_Push-Up"},{"id":"Decline_Push-Up","name":"Decline press-up","group":"Home basics","type":"Strength","area":"Chest","muscles":["chest"],"secondary":["shoulders","triceps"],"equipment":["Bench"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length. Move your feet up to a box or bench. This will be your starting position.","Next, lower yourself downward until your chest almost touches the floor as you inhale.","Now breathe out and press your upper body back up to the starting position while squeezing your chest.","After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed."],"cues":["Keep wrists aligned with forearms.","Brace your trunk.","Press smoothly; avoid bouncing."],"images":["assets/exercises/Decline_Push-Up/0.webp","assets/exercises/Decline_Push-Up/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Decline_Push-Up"},{"id":"Push-Up_Wide","name":"Wide press-up","group":"Home basics","type":"Strength","area":"Chest","muscles":["chest"],"secondary":["abdominals","shoulders","triceps"],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["With your hands wide apart, support your body on your toes and hands in a plank position. Your elbows should be extended and your body straight. Do not allow your hips to sag. This will be your starting position.","To begin, allow the elbows to flex, lowering your chest to the floor as you inhale.","Using your pectoral muscles, press your upper body back up to the starting position by extending the elbows. Exhale as you perform this step.","After pausing at the contracted position, repeat the movement for the prescribed amount of repetitions."],"cues":["Keep wrists aligned with forearms.","Brace your trunk.","Press smoothly; avoid bouncing."],"images":["assets/exercises/Push-Up_Wide/0.webp","assets/exercises/Push-Up_Wide/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Push-Up_Wide"},{"id":"Butt_Lift_Bridge","name":"Glute bridge","group":"Home basics","type":"Strength","area":"Glutes","muscles":["glutes"],"secondary":["hamstrings"],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position.","Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second.","Slowly go back to the starting position as you breathe in."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Butt_Lift_Bridge/0.webp","assets/exercises/Butt_Lift_Bridge/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Butt_Lift_Bridge"},{"id":"Single_Leg_Glute_Bridge","name":"Single leg glute bridge","group":"Home basics","type":"Strength","area":"Glutes","muscles":["glutes"],"secondary":["hamstrings"],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":true,"instructions":["Lay on the floor with your feet flat and knees bent.","Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position.","Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground.","Extend as far as possible, pause and then return to the starting position."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Single_Leg_Glute_Bridge/0.webp","assets/exercises/Single_Leg_Glute_Bridge/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Single_Leg_Glute_Bridge"},{"id":"Plank","name":"Plank","group":"Home basics","type":"Strength","area":"Core","muscles":["abdominals"],"secondary":[],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.","Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised."],"cues":["Keep a long line through your body.","Brace without holding your breath.","Stop before your posture drops."],"images":["assets/exercises/Plank/0.webp","assets/exercises/Plank/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Plank"},{"id":"Side_Bridge","name":"Side plank","group":"Home basics","type":"Strength","area":"Core","muscles":["abdominals"],"secondary":["shoulders"],"equipment":["Bodyweight"],"location":"Home & gym","level":"Intermediate","mode":"time","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":true,"instructions":["Lie on one side with your legs extended and feet stacked. Place your forearm on the floor with the elbow beneath your shoulder.","Gently brace your trunk and lift your hips so your body forms a straight line from head to feet. Keep the neck aligned and the shoulder supported.","Hold while breathing steadily. Lower under control before your position sags, then repeat on the other side. For an easier variation, bend the knees and support yourself through the forearm and lower knee."],"cues":["Keep a long line through your body.","Brace without holding your breath.","Stop before your posture drops."],"images":["assets/exercises/Side_Bridge/0.webp","assets/exercises/Side_Bridge/1.webp"],"source":"https://www.acefitness.org/resources/everyone/exercise-library/101/side-plank-with-straight-leg/"},{"id":"Dead_Bug","name":"Dead bug","group":"Home basics","type":"Strength","area":"Core","muscles":["abdominals"],"secondary":[],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Begin lying on your back with your hands extended above you toward the ceiling.","Bring your feet, knees, and hips up to 90 degrees.","Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position.","Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.","Maintain the position of your lumbar and pelvis as you perform the movement, as your back is going to want to arch.","Stay tight and return the working leg to the starting position.","Repeat on the opposite side, alternating until the set is complete."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Dead_Bug/0.webp","assets/exercises/Dead_Bug/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Dead_Bug"},{"id":"Crunches","name":"Crunches","group":"Home basics","type":"Strength","area":"Core","muscles":["abdominals"],"secondary":[],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle. If you are resting your feet on a bench, place them three to four inches apart and point your toes inward so they touch.","Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don't lock your fingers behind your head.","While pushing the small of your back down in the floor to better isolate your abdominal muscles, begin to roll your shoulders off the floor.","Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don't cheat yourself by using momentum.","After the one second contraction, begin to come down slowly again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Crunches/0.webp","assets/exercises/Crunches/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Crunches"},{"id":"Reverse_Crunch","name":"Reverse crunch","group":"Home basics","type":"Strength","area":"Core","muscles":["abdominals"],"secondary":[],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Lie down on the floor with your legs fully extended and arms to the side of your torso with the palms on the floor. Your arms should be stationary for the entire exercise.","Move your legs up so that your thighs are perpendicular to the floor and feet are together and parallel to the floor. This is the starting position.","While inhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the floor. At the end of this movement your knees will be touching your chest.","Hold the contraction for a second and move your legs back to the starting position while exhaling.","Repeat for the recommended amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Reverse_Crunch/0.webp","assets/exercises/Reverse_Crunch/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Reverse_Crunch"},{"id":"Air_Bike","name":"Bicycle crunch","group":"Home basics","type":"Strength","area":"Core","muscles":["abdominals"],"secondary":[],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position.","Bring knees up to where they are perpendicular to the floor, with your lower legs parallel to the floor. This will be your starting position.","Now simultaneously, slowly go through a cycle pedal motion kicking forward with the right leg and bringing in the knee of the left leg. Bring your right elbow close to your left knee by crunching to the side, as you breathe out.","Go back to the initial position as you breathe in.","Crunch to the opposite side as you cycle your legs and bring closer your left elbow to your right knee and exhale.","Continue alternating in this manner until all of the recommended repetitions for each side have been completed."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Air_Bike/0.webp","assets/exercises/Air_Bike/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Air_Bike"},{"id":"Alternate_Heel_Touchers","name":"Alternate heel touchers","group":"Home basics","type":"Strength","area":"Core","muscles":["abdominals"],"secondary":[],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Lie on the floor with the knees bent and the feet on the floor around 18-24 inches apart. Your arms should be extended by your side. This will be your starting position.","Crunch over your torso forward and up about 3-4 inches to the right side and touch your right heel as you hold the contraction for a second. Exhale while performing this movement.","Now go back slowly to the starting position as you inhale.","Now crunch over your torso forward and up around 3-4 inches to the left side and touch your left heel as you hold the contraction for a second. Exhale while performing this movement and then go back to the starting position as you inhale. Now that both heels have been touched, that is considered 1 repetition.","Continue alternating sides in this manner until all prescribed repetitions are done."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Alternate_Heel_Touchers/0.webp","assets/exercises/Alternate_Heel_Touchers/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Alternate_Heel_Touchers"},{"id":"Mountain_Climbers","name":"Mountain climbers","group":"Home basics","type":"Strength","area":"Core","muscles":["abdominals"],"secondary":["chest","hamstrings","shoulders"],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Begin in a pushup position, with your weight supported by your hands and toes. Flexing the knee and hip, bring one leg until the knee is approximately under the hip. This will be your starting position.","Explosively reverse the positions of your legs, extending the bent leg until the leg is straight and supported by the toe, and bringing the other foot up with the hip and knee flexed. Repeat in an alternating fashion for 20-30 seconds."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Mountain_Climbers/0.webp","assets/exercises/Mountain_Climbers/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Mountain_Climbers"},{"id":"Superman","name":"Superman","group":"Home basics","type":"Stretch","area":"Back","muscles":["lower back"],"secondary":["glutes","hamstrings"],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":false,"instructions":["To begin, lie straight and face down on the floor or exercise mat. Your arms should be fully extended in front of you. This is the starting position.","Simultaneously raise your arms, legs, and chest off of the floor and hold this contraction for 2 seconds. Tip: Squeeze your lower back to get the best results from this exercise. Remember to exhale during this movement. Note: When holding the contracted position, you should look like superman when he is flying.","Slowly begin to lower your arms, legs and chest back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions prescribed in your program."],"cues":["Ease into gentle tension.","Breathe slowly; do not bounce.","Stay within a comfortable range."],"images":["assets/exercises/Superman/0.webp","assets/exercises/Superman/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Superman"},{"id":"Glute_Kickback","name":"Glute kickback","group":"Home basics","type":"Strength","area":"Glutes","muscles":["glutes"],"secondary":["hamstrings"],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":true,"instructions":["Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.","As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 90-degree angle bend. Contract the glutes throughout this movement and hold the contraction at the top for a second. Tip: At the end of the movement the upper leg should be parallel to the floor while the calf should be perpendicular to it.","Go back to the initial position as you inhale and now repeat with the left leg.","Continue to alternate legs until all of the recommended repetitions have been performed."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Glute_Kickback/0.webp","assets/exercises/Glute_Kickback/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Glute_Kickback"},{"id":"Bodyweight_Walking_Lunge","name":"Bodyweight walking lunge","group":"Home basics","type":"Strength","area":"Legs","muscles":["quadriceps"],"secondary":["calves","glutes","hamstrings"],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Begin standing with your feet shoulder width apart and your hands on your hips.","Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.","Drive through the heel of your lead foot and extend both knees to raise yourself back up.","Step forward with your rear foot, repeating the lunge on the opposite leg."],"cues":["Keep your feet planted.","Let knees follow the toes.","Keep the movement controlled."],"images":["assets/exercises/Bodyweight_Walking_Lunge/0.webp","assets/exercises/Bodyweight_Walking_Lunge/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Bodyweight_Walking_Lunge"},{"id":"Step-up_with_Knee_Raise","name":"Step-up with knee raise","group":"Home basics","type":"Strength","area":"Glutes","muscles":["glutes"],"secondary":["hamstrings","quadriceps"],"equipment":["Step"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position.","Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can.","Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Step-up_with_Knee_Raise/0.webp","assets/exercises/Step-up_with_Knee_Raise/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Step-up_with_Knee_Raise"},{"id":"Inchworm","name":"Inchworm","group":"Home basics","type":"Mobility","area":"Legs","muscles":["hamstrings"],"secondary":[],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":false,"instructions":["Stand with your feet close together. Keeping your legs straight, stretch down and put your hands on the floor directly in front of you. This will be your starting position.","Begin by walking your hands forward slowly, alternating your left and your right. As you do so, bend only at the hip, keeping your legs straight.","Keep going until your body is parallel to the ground in a pushup position.","Now, keep your hands in place and slowly take short steps with your feet, moving only a few inches at a time.","Continue walking until your feet are by hour hands, keeping your legs straight as you do so."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Inchworm/0.webp","assets/exercises/Inchworm/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Inchworm"},{"id":"Flutter_Kicks","name":"Flutter kicks","group":"Home basics","type":"Strength","area":"Core","muscles":["abdominals"],"secondary":["hamstrings"],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["On a flat bench lie facedown with the hips on the edge of the bench, the legs straight with toes high off the floor and with the arms on top of the bench holding on to the front edge.","Squeeze your glutes and hamstrings and straighten the legs until they are level with the hips. This will be your starting position.","Start the movement by lifting the left leg higher than the right leg.","Then lower the left leg as you lift the right leg.","Continue alternating in this manner (as though you are doing a flutter kick in water) until you have done the recommended amount of repetitions for each leg. Make sure that you keep a controlled movement at all times. Tip: You will breathe normally as you perform this movement."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Flutter_Kicks/0.webp","assets/exercises/Flutter_Kicks/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Flutter_Kicks"},{"id":"Standing_Calf_Raises","name":"Standing calf raises","group":"Home basics","type":"Strength","area":"Calves","muscles":["calves"],"secondary":[],"equipment":["Machine"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Adjust the padded lever of the calf raise machine to fit your height.","Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be facing forward, outwards or inwards as described at the beginning of the chapter. This will be your starting position.","Raise your heels as you breathe out by extending your ankles as high as possible and flexing your calf. Ensure that the knee is kept stationary at all times. There should be no bending at any time. Hold the contracted position by a second before you start to go back down.","Go back slowly to the starting position as you breathe in by lowering your heels as you bend the ankles until calves are stretched.","Repeat for the recommended amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Standing_Calf_Raises/0.webp","assets/exercises/Standing_Calf_Raises/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Standing_Calf_Raises"},{"id":"Dumbbell_Squat","name":"Dumbbell squat","group":"Dumbbells","type":"Strength","area":"Legs","muscles":["quadriceps"],"secondary":["calves","glutes","hamstrings","lower back"],"equipment":["Dumbbells"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).","Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section.","Begin to slowly lower your torso by bending the knees as you maintain a straight posture with the head up. Continue down until your thighs are parallel to the floor. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise your torso as you exhale by pushing the floor with the heel of your foot mainly as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"cues":["Keep your feet planted.","Let knees follow the toes.","Keep the movement controlled."],"images":["assets/exercises/Dumbbell_Squat/0.webp","assets/exercises/Dumbbell_Squat/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Dumbbell_Squat"},{"id":"Dumbbell_Floor_Press","name":"Dumbbell floor press","group":"Dumbbells","type":"Strength","area":"Chest","muscles":["chest","triceps"],"secondary":["chest","shoulders"],"equipment":["Dumbbells"],"location":"Home & gym","level":"Intermediate","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Lay on the floor holding dumbbells in your hands. Your knees can be bent. Begin with the weights fully extended above you.","Lower the weights until your upper arm comes in contact with the floor. You can tuck your elbows to emphasize triceps size and strength, or to focus on your chest angle your arms to the side.","Pause at the bottom, and then bring the weight together at the top by extending through the elbows."],"cues":["Keep wrists aligned with forearms.","Brace your trunk.","Press smoothly; avoid bouncing."],"images":["assets/exercises/Dumbbell_Floor_Press/0.webp","assets/exercises/Dumbbell_Floor_Press/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Dumbbell_Floor_Press"},{"id":"Dumbbell_Bench_Press","name":"Dumbbell bench press","group":"Dumbbells","type":"Strength","area":"Chest","muscles":["chest"],"secondary":["shoulders","triceps"],"equipment":["Dumbbells","Bench"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other.","Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.","Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 degree angle. Be sure to maintain full control of the dumbbells at all times. This will be your starting position.","Then, as you breathe out, use your chest to push the dumbbells up. Lock your arms at the top of the lift and squeeze your chest, hold for a second and then begin coming down slowly. Tip: Ideally, lowering the weight should take about twice as long as raising it.","Repeat the movement for the prescribed amount of repetitions of your training program."],"cues":["Keep wrists aligned with forearms.","Brace your trunk.","Press smoothly; avoid bouncing."],"images":["assets/exercises/Dumbbell_Bench_Press/0.webp","assets/exercises/Dumbbell_Bench_Press/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Dumbbell_Bench_Press"},{"id":"Dumbbell_Bench_Press_with_Neutral_Grip","name":"Dumbbell bench press with neutral grip","group":"Dumbbells","type":"Strength","area":"Chest","muscles":["chest"],"secondary":["shoulders","triceps"],"equipment":["Dumbbells","Bench"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Take a dumbbell in each hand and lay back onto a flat bench. Your feet should be flat on the floor and your shoulder blades retracted.","Maintaining a neutral grip, palms facing each other, begin with your arms extended directly above you, perpendicular to the floor. This will be your starting position.","Begin the movement by flexing the elbow, lowering the upper arms to the side. Descend until the dumbbells are to your torso.","Pause, then extend the elbow and return to the starting position."],"cues":["Keep wrists aligned with forearms.","Brace your trunk.","Press smoothly; avoid bouncing."],"images":["assets/exercises/Dumbbell_Bench_Press_with_Neutral_Grip/0.webp","assets/exercises/Dumbbell_Bench_Press_with_Neutral_Grip/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Dumbbell_Bench_Press_with_Neutral_Grip"},{"id":"Incline_Dumbbell_Press","name":"Incline dumbbell press","group":"Dumbbells","type":"Strength","area":"Chest","muscles":["chest"],"secondary":["shoulders","triceps"],"equipment":["Dumbbells","Bench"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.","Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.","Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.","Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.","Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the dumbbells back on your thighs and then on the floor. This is the safest manner to release the dumbbells."],"cues":["Keep wrists aligned with forearms.","Brace your trunk.","Press smoothly; avoid bouncing."],"images":["assets/exercises/Incline_Dumbbell_Press/0.webp","assets/exercises/Incline_Dumbbell_Press/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Incline_Dumbbell_Press"},{"id":"Dumbbell_Flyes","name":"Dumbbell flyes","group":"Dumbbells","type":"Strength","area":"Chest","muscles":["chest"],"secondary":[],"equipment":["Dumbbells","Bench"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other.","Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you're pressing them, but stop and hold just before you lock out. This will be your starting position.","With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary; the movement should only occur at the shoulder joint.","Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.","Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Dumbbell_Flyes/0.webp","assets/exercises/Dumbbell_Flyes/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Dumbbell_Flyes"},{"id":"Incline_Dumbbell_Flyes","name":"Incline dumbbell flyes","group":"Dumbbells","type":"Strength","area":"Chest","muscles":["chest"],"secondary":["shoulders"],"equipment":["Dumbbells","Bench"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Hold a dumbbell on each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.","Extend your arms above you with a slight bend at the elbows.","Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position.","As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other. Tip: At the end of the movement the arms will be by your side with the palms facing the ceiling.","As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. Tip: Keep in mind that the movement will only happen at the shoulder joint and at the wrist. There is no motion that happens at the elbow joint.","Repeat for the recommended amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Incline_Dumbbell_Flyes/0.webp","assets/exercises/Incline_Dumbbell_Flyes/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Incline_Dumbbell_Flyes"},{"id":"One-Arm_Dumbbell_Row","name":"Single-arm dumbbell row","group":"Dumbbells","type":"Strength","area":"Back","muscles":["middle back"],"secondary":["biceps","lats","shoulders"],"equipment":["Dumbbells","Bench"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":true,"instructions":["Choose a flat bench and place a dumbbell on each side of it.","Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.","Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.","Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.","Lower the resistance straight down to the starting position. Breathe in as you perform this step.","Repeat the movement for the specified amount of repetitions.","Switch sides and repeat again with the other arm."],"cues":["Keep your torso steady.","Lead with your elbows.","Lower the weight with control."],"images":["assets/exercises/One-Arm_Dumbbell_Row/0.webp","assets/exercises/One-Arm_Dumbbell_Row/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/One-Arm_Dumbbell_Row"},{"id":"Bent_Over_Two-Dumbbell_Row","name":"Bent over two-dumbbell row","group":"Dumbbells","type":"Strength","area":"Back","muscles":["middle back"],"secondary":["biceps","lats","shoulders"],"equipment":["Dumbbells"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["With a dumbbell in each hand (palms facing your torso), bend your knees slightly and bring your torso forward by bending at the waist; as you bend make sure to keep your back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.","While keeping the torso stationary, lift the dumbbells to your side (as you breathe out), keeping the elbows close to the body (do not exert any force with the forearm other than holding the weights). On the top contracted position, squeeze the back muscles and hold for a second.","Slowly lower the weight again to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"cues":["Keep your torso steady.","Lead with your elbows.","Lower the weight with control."],"images":["assets/exercises/Bent_Over_Two-Dumbbell_Row/0.webp","assets/exercises/Bent_Over_Two-Dumbbell_Row/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Bent_Over_Two-Dumbbell_Row"},{"id":"Dumbbell_Incline_Row","name":"Dumbbell incline row","group":"Dumbbells","type":"Strength","area":"Back","muscles":["middle back"],"secondary":["biceps","forearms","lats","shoulders"],"equipment":["Dumbbells","Bench"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Using a neutral grip, lean into an incline bench.","Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position.","Retract the shoulder blades and flex the elbows to row the dumbbells to your side.","Pause at the top of the motion, and then return to the starting position."],"cues":["Keep your torso steady.","Lead with your elbows.","Lower the weight with control."],"images":["assets/exercises/Dumbbell_Incline_Row/0.webp","assets/exercises/Dumbbell_Incline_Row/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Dumbbell_Incline_Row"},{"id":"Dumbbell_Lunges","name":"Dumbbell lunges","group":"Dumbbells","type":"Strength","area":"Legs","muscles":["quadriceps"],"secondary":["calves","glutes","hamstrings"],"equipment":["Dumbbells"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position.","Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin perpendicular to the ground.","Using mainly the heel of your foot, push up and go back to the starting position as you exhale.","Repeat the movement for the recommended amount of repetitions and then perform with the left leg."],"cues":["Keep your feet planted.","Let knees follow the toes.","Keep the movement controlled."],"images":["assets/exercises/Dumbbell_Lunges/0.webp","assets/exercises/Dumbbell_Lunges/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Dumbbell_Lunges"},{"id":"Split_Squat_with_Dumbbells","name":"Split squat with dumbbells","group":"Dumbbells","type":"Strength","area":"Legs","muscles":["quadriceps"],"secondary":["glutes","hamstrings"],"equipment":["Dumbbells","Bench"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":true,"instructions":["Position yourself into a staggered stance with the rear foot elevated and front foot forward.","Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position.","Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise.","At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position."],"cues":["Keep your feet planted.","Let knees follow the toes.","Keep the movement controlled."],"images":["assets/exercises/Split_Squat_with_Dumbbells/0.webp","assets/exercises/Split_Squat_with_Dumbbells/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Split_Squat_with_Dumbbells"},{"id":"Dumbbell_Step_Ups","name":"Dumbbell step ups","group":"Dumbbells","type":"Strength","area":"Legs","muscles":["quadriceps"],"secondary":["calves","glutes","hamstrings"],"equipment":["Dumbbells","Step"],"location":"Home & gym","level":"Intermediate","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs).","Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up.","Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original standing position by placing the right foot of to next to the left foot on the initial position.","Repeat with the right leg for the recommended amount of repetitions and then perform with the left leg."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Dumbbell_Step_Ups/0.webp","assets/exercises/Dumbbell_Step_Ups/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Dumbbell_Step_Ups"},{"id":"Stiff-Legged_Dumbbell_Deadlift","name":"Dumbbell stiff-leg deadlift","group":"Dumbbells","type":"Strength","area":"Legs","muscles":["hamstrings"],"secondary":["glutes","lower back"],"equipment":["Dumbbells"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Grasp a couple of dumbbells holding them by your side at arm's length.","Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.","Keeping the knees stationary, lower the dumbbells to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement","Start bringing your torso up straight again by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.","Repeat for the recommended amount of repetitions."],"cues":["Send your hips backwards.","Keep the weight close.","Maintain a steady, neutral spine."],"images":["assets/exercises/Stiff-Legged_Dumbbell_Deadlift/0.webp","assets/exercises/Stiff-Legged_Dumbbell_Deadlift/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Stiff-Legged_Dumbbell_Deadlift"},{"id":"Dumbbell_Bicep_Curl","name":"Dumbbell curl","group":"Dumbbells","type":"Strength","area":"Arms","muscles":["biceps"],"secondary":["forearms"],"equipment":["Dumbbells"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Stand up straight with a dumbbell in each hand at arm's length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.","Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps.","Then, inhale and slowly begin to lower the dumbbells back to the starting position.","Repeat for the recommended amount of repetitions."],"cues":["Keep elbows close to your sides.","Avoid swinging the weight.","Lower slowly and smoothly."],"images":["assets/exercises/Dumbbell_Bicep_Curl/0.webp","assets/exercises/Dumbbell_Bicep_Curl/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Dumbbell_Bicep_Curl"},{"id":"Hammer_Curls","name":"Hammer curls","group":"Dumbbells","type":"Strength","area":"Arms","muscles":["biceps"],"secondary":[],"equipment":["Dumbbells"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.","The palms of the hands should be facing your torso. This will be your starting position.","Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.","After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.","Repeat for the recommended amount of repetitions."],"cues":["Keep elbows close to your sides.","Avoid swinging the weight.","Lower slowly and smoothly."],"images":["assets/exercises/Hammer_Curls/0.webp","assets/exercises/Hammer_Curls/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Hammer_Curls"},{"id":"Concentration_Curls","name":"Concentration curls","group":"Dumbbells","type":"Strength","area":"Arms","muscles":["biceps"],"secondary":["forearms"],"equipment":["Dumbbells","Bench"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":true,"instructions":["Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor.","Use your right arm to pick the dumbbell up. Place the back of your right upper arm on the top of your inner right thigh. Rotate the palm of your hand until it is facing forward away from your thigh. Tip: Your arm should be extended and the dumbbell should be above the floor. This will be your starting position.","While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Tip: At the top of the movement make sure that the little finger of your arm is higher than your thumb. This guarantees a good contraction. Hold the contracted position for a second as you squeeze the biceps.","Slowly begin to bring the dumbbells back to starting position as your breathe in. Caution: Avoid swinging motions at any time.","Repeat for the recommended amount of repetitions. Then repeat the movement with the left arm."],"cues":["Keep elbows close to your sides.","Avoid swinging the weight.","Lower slowly and smoothly."],"images":["assets/exercises/Concentration_Curls/0.webp","assets/exercises/Concentration_Curls/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Concentration_Curls"},{"id":"Incline_Dumbbell_Curl","name":"Incline dumbbell curl","group":"Dumbbells","type":"Strength","area":"Arms","muscles":["biceps"],"secondary":[],"equipment":["Dumbbells","Bench"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Sit back on an incline bench with a dumbbell in each hand held at arms length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position.","While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second.","Slowly begin to bring the dumbbells back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"cues":["Keep elbows close to your sides.","Avoid swinging the weight.","Lower slowly and smoothly."],"images":["assets/exercises/Incline_Dumbbell_Curl/0.webp","assets/exercises/Incline_Dumbbell_Curl/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Incline_Dumbbell_Curl"},{"id":"Seated_Dumbbell_Curl","name":"Seated dumbbell curl","group":"Dumbbells","type":"Strength","area":"Arms","muscles":["biceps"],"secondary":[],"equipment":["Dumbbells","Bench"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Sit on a flat bench with a dumbbell on each hand being held at arms length. The elbows should be close to the torso.","Rotate the palms of the hands so that they are facing your torso. This will be your starting position.","While holding the upper arm stationary, curl the weights and start twisting the wrists once the dumbbells pass your thighs so that the palms of your hands face forward at the end of the movement. Make sure that you contract the biceps as you breathe out and make sure that only the forearms move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps.","Slowly begin to bring the dumbbells back to the starting position as your breathe in and as you rotate the wrists back to a neutral grip.","Repeat for the recommended amount of repetitions."],"cues":["Keep elbows close to your sides.","Avoid swinging the weight.","Lower slowly and smoothly."],"images":["assets/exercises/Seated_Dumbbell_Curl/0.webp","assets/exercises/Seated_Dumbbell_Curl/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Seated_Dumbbell_Curl"},{"id":"Standing_Dumbbell_Press","name":"Standing dumbbell press","group":"Dumbbells","type":"Strength","area":"Shoulders","muscles":["shoulders"],"secondary":["triceps"],"equipment":["Dumbbells"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Standing with your feet shoulder width apart, take a dumbbell in each hand. Raise the dumbbells to head height, the elbows out and about 90 degrees. This will be your starting position.","Maintaining strict technique with no leg drive or leaning back, extend through the elbow to raise the weights together directly above your head.","Pause, and slowly return the weight to the starting position."],"cues":["Keep wrists aligned with forearms.","Brace your trunk.","Press smoothly; avoid bouncing."],"images":["assets/exercises/Standing_Dumbbell_Press/0.webp","assets/exercises/Standing_Dumbbell_Press/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Standing_Dumbbell_Press"},{"id":"Seated_Dumbbell_Press","name":"Seated dumbbell press","group":"Dumbbells","type":"Strength","area":"Shoulders","muscles":["shoulders"],"secondary":["triceps"],"equipment":["Dumbbells","Bench"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Grab a couple of dumbbells and sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs.","Clean the dumbbells up one at a time by using your thighs to bring the dumbbells up to shoulder height at each side.","Rotate the wrists so that the palms of your hands are facing forward. This is your starting position.","As you exhale, push the dumbbells up until they touch at the top.","After a second pause, slowly come down back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"cues":["Keep wrists aligned with forearms.","Brace your trunk.","Press smoothly; avoid bouncing."],"images":["assets/exercises/Seated_Dumbbell_Press/0.webp","assets/exercises/Seated_Dumbbell_Press/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Seated_Dumbbell_Press"},{"id":"Side_Lateral_Raise","name":"Side lateral raise","group":"Dumbbells","type":"Strength","area":"Shoulders","muscles":["shoulders"],"secondary":[],"equipment":["Dumbbells"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.","While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.","Lower the dumbbells back down slowly to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Side_Lateral_Raise/0.webp","assets/exercises/Side_Lateral_Raise/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Side_Lateral_Raise"},{"id":"Front_Dumbbell_Raise","name":"Front dumbbell raise","group":"Dumbbells","type":"Strength","area":"Shoulders","muscles":["shoulders"],"secondary":[],"equipment":["Dumbbells"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position.","While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause for a second at the top. Inhale after the second pause.","Now lower the dumbbell back down slowly to the starting position as you simultaneously lift the right dumbbell.","Continue alternating in this fashion until all of the recommended amount of repetitions have been performed for each arm."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Front_Dumbbell_Raise/0.webp","assets/exercises/Front_Dumbbell_Raise/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Front_Dumbbell_Raise"},{"id":"Reverse_Flyes","name":"Reverse flyes","group":"Dumbbells","type":"Strength","area":"Shoulders","muscles":["shoulders"],"secondary":[],"equipment":["Dumbbells","Bench"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["To begin, lie down on an incline bench with the chest and stomach pressing against the incline. Have the dumbbells in each hand with the palms facing each other (neutral grip).","Extend the arms in front of you so that they are perpendicular to the angle of the bench. The legs should be stationary while applying pressure with the ball of your toes. This is the starting position.","Maintaining the slight bend of the elbows, move the weights out and away from each other (to the side) in an arc motion while exhaling. Tip: Try to squeeze your shoulder blades together to get the best results from this exercise.","The arms should be elevated until they are parallel to the floor.","Feel the contraction and slowly lower the weights back down to the starting position while inhaling.","Repeat for the recommended amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Reverse_Flyes/0.webp","assets/exercises/Reverse_Flyes/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Reverse_Flyes"},{"id":"Dumbbell_Shrug","name":"Dumbbell shrug","group":"Dumbbells","type":"Strength","area":"Back","muscles":["traps"],"secondary":[],"equipment":["Dumbbells"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides.","Lift the dumbbells by elevating the shoulders as high as possible while you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the dumbbells. Only the shoulders should be moving up and down.","Lower the dumbbells back to the original position.","Repeat for the recommended amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Dumbbell_Shrug/0.webp","assets/exercises/Dumbbell_Shrug/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Dumbbell_Shrug"},{"id":"Tricep_Dumbbell_Kickback","name":"Triceps kickback","group":"Dumbbells","type":"Strength","area":"Arms","muscles":["triceps"],"secondary":[],"equipment":["Dumbbells"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":true,"instructions":["Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position.","Now, while keeping your upper arms stationary, exhale and use your triceps to lift the weights until the arm is fully extended. Focus on moving the forearm.","After a brief pause at the top contraction, inhale and slowly lower the dumbbells back down to the starting position.","Repeat the movement for the prescribed amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Tricep_Dumbbell_Kickback/0.webp","assets/exercises/Tricep_Dumbbell_Kickback/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Tricep_Dumbbell_Kickback"},{"id":"Standing_Dumbbell_Triceps_Extension","name":"Standing dumbbell triceps extension","group":"Dumbbells","type":"Strength","area":"Arms","muscles":["triceps"],"secondary":[],"equipment":["Dumbbells"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["To begin, stand up with a dumbbell held by both hands. Your feet should be about shoulder width apart from each other. Slowly use both hands to grab the dumbbell and lift it over your head until both arms are fully extended.","The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hands should be facing up towards the ceiling. This will be your starting position.","Keeping your upper arms close to your head with elbows in and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.","Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.","Repeat for the recommended amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Standing_Dumbbell_Triceps_Extension/0.webp","assets/exercises/Standing_Dumbbell_Triceps_Extension/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Standing_Dumbbell_Triceps_Extension"},{"id":"Seated_Triceps_Press","name":"Seated triceps press","group":"Dumbbells","type":"Strength","area":"Arms","muscles":["triceps"],"secondary":[],"equipment":["Dumbbells","Bench"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Sit down on a bench with back support and grasp a dumbbell with both hands and hold it overhead at arm's length. Tip: a better way is to have somebody hand it to you especially if it is very heavy. The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hand should be facing inward. This will be your starting position.","Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semi-circular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.","Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.","Repeat for the recommended amount of repetitions."],"cues":["Keep wrists aligned with forearms.","Brace your trunk.","Press smoothly; avoid bouncing."],"images":["assets/exercises/Seated_Triceps_Press/0.webp","assets/exercises/Seated_Triceps_Press/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Seated_Triceps_Press"},{"id":"Dumbbell_Seated_One-Leg_Calf_Raise","name":"Dumbbell seated one-leg calf raise","group":"Dumbbells","type":"Strength","area":"Calves","muscles":["calves"],"secondary":[],"equipment":["Dumbbells","Bench"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":true,"instructions":["Place a block on the floor about 12 inches from a flat bench.","Sit on a flat bench and place a dumbbell on your upper left thigh about 3 inches above your knee.","Now place the ball of your left foot on the block. This will be your starting position.","Raise your toes up as high as possible as you exhale and you contract your calf muscle. Hold the contraction for a second.","Slowly return to the starting position, stretching as far down as possible.","Repeat for your prescribed number of repetitions and then repeat with the right leg."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Dumbbell_Seated_One-Leg_Calf_Raise/0.webp","assets/exercises/Dumbbell_Seated_One-Leg_Calf_Raise/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Dumbbell_Seated_One-Leg_Calf_Raise"},{"id":"Band_Pull_Apart","name":"Band pull apart","group":"Bands & kettlebells","type":"Strength","area":"Shoulders","muscles":["shoulders"],"secondary":["middle back","traps"],"equipment":["Bands"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Begin with your arms extended straight out in front of you, holding the band with both hands.","Initiate the movement by performing a reverse fly motion, moving your hands out laterally to your sides.","Keep your elbows extended as you perform the movement, bringing the band to your chest. Ensure that you keep your shoulders back during the exercise.","Pause as you complete the movement, returning to the starting position under control."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Band_Pull_Apart/0.webp","assets/exercises/Band_Pull_Apart/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Band_Pull_Apart"},{"id":"Back_Flyes_-_With_Bands","name":"Back flyes - with bands","group":"Bands & kettlebells","type":"Strength","area":"Shoulders","muscles":["shoulders"],"secondary":["middle back","triceps"],"equipment":["Bands"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Run a band around a stationary post like that of a squat rack.","Grab the band by the handles and stand back so that the tension in the band rises.","Extend and lift the arms straight in front of you. Tip: Your arms should be straight and parallel to the floor while perpendicular to your torso. Your feet should be firmly planted on the floor spread at shoulder width. This will be your starting position.","As you exhale, move your arms to the sides and back. Keep your arms extended and parallel to the floor. Continue the movement until the arms are extended to your sides.","After a pause, go back to the original position as you inhale.","Repeat for the recommended amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Back_Flyes_-_With_Bands/0.webp","assets/exercises/Back_Flyes_-_With_Bands/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Back_Flyes_-_With_Bands"},{"id":"Shoulder_Press_-_With_Bands","name":"Shoulder press - with bands","group":"Bands & kettlebells","type":"Strength","area":"Shoulders","muscles":["shoulders"],"secondary":["triceps"],"equipment":["Bands"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["To begin, stand on an exercise band so that tension begins at arm's length. Grasp the handles and lift them so that the hands are at shoulder height at each side.","Rotate the wrists so that the palms of your hands are facing forward. Your elbows should be bent, with the upper arms and forearms in line to the torso. This is your starting position.","As you exhale, lift the handles up until your arms are fully extended overhead."],"cues":["Keep wrists aligned with forearms.","Brace your trunk.","Press smoothly; avoid bouncing."],"images":["assets/exercises/Shoulder_Press_-_With_Bands/0.webp","assets/exercises/Shoulder_Press_-_With_Bands/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Shoulder_Press_-_With_Bands"},{"id":"Lateral_Raise_-_With_Bands","name":"Lateral raise - with bands","group":"Bands & kettlebells","type":"Strength","area":"Shoulders","muscles":["shoulders"],"secondary":[],"equipment":["Bands"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["To begin, stand on an exercise band so that tension begins at arm's length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on the sides of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position.","Use your side shoulders to lift the handles to the sides as you exhale. Continue to lift the handles until they are slightly above parallel. Tip: As you lift the handles, slightly tilt the hand as if you were pouring water and keep your arms extended. Also, keep your torso stationary and pause for a second at the top of the movement.","Lower the handles back down slowly to the starting position. Inhale as you perform this portion of the movement.","Repeat for the recommended amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Lateral_Raise_-_With_Bands/0.webp","assets/exercises/Lateral_Raise_-_With_Bands/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Lateral_Raise_-_With_Bands"},{"id":"Squats_-_With_Bands","name":"Squats - with bands","group":"Bands & kettlebells","type":"Strength","area":"Legs","muscles":["quadriceps"],"secondary":["calves","glutes","hamstrings","lower back"],"equipment":["Bands"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["To start out, make sure that the exercise band is at an even split between both the left and right side of the body. To do this, use your hands to grab both sides of the band and place both feet in the middle of the band. Your feet should be shoulder width apart from each other.","When holding the bands, they should be the same height on each side. You should be using a pronated grip (palms facing forward) and have the handles of the bands next to your face for this exercise. This is the starting position.","Slowly start to bend the knees and lower the legs so that your thighs are parallel to the floor while exhaling.","Use the heel of your feet to push your body up to the starting position as you exhale.","Repeat for the recommended amount of repetitions."],"cues":["Keep your feet planted.","Let knees follow the toes.","Keep the movement controlled."],"images":["assets/exercises/Squats_-_With_Bands/0.webp","assets/exercises/Squats_-_With_Bands/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Squats_-_With_Bands"},{"id":"External_Rotation_with_Band","name":"External rotation with band","group":"Bands & kettlebells","type":"Strength","area":"Shoulders","muscles":["shoulders"],"secondary":[],"equipment":["Bands"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":true,"instructions":["Choke the band around a post. The band should be at the same height as your elbow. Stand with your left side to the band a couple of feet away.","Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position.","With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position.","Execute the movement by rotating your arm in a backhand motion, keeping your elbow in place.","Continue as far as you are able, pause, and then return to the starting position."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/External_Rotation_with_Band/0.webp","assets/exercises/External_Rotation_with_Band/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/External_Rotation_with_Band"},{"id":"Hip_Extension_with_Bands","name":"Hip extension with bands","group":"Bands & kettlebells","type":"Strength","area":"Glutes","muscles":["glutes"],"secondary":["hamstrings"],"equipment":["Bands"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":true,"instructions":["Secure one end of the band to the lower portion of a post and attach the other to one ankle.","Facing the attachment point of the band, hold on to the column to stabilize yourself.","Keeping your head and your chest up, move the resisted leg back as far as you can while keeping the knee straight.","Return the leg to the starting position."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Hip_Extension_with_Bands/0.webp","assets/exercises/Hip_Extension_with_Bands/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Hip_Extension_with_Bands"},{"id":"Hip_Flexion_with_Band","name":"Hip flexion with band","group":"Bands & kettlebells","type":"Strength","area":"Legs","muscles":["quadriceps"],"secondary":[],"equipment":["Bands"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":true,"instructions":["Secure one end of the band to the lower portion of a post and attach the other to one ankle.","Face away from the attachment point of the band.","Keeping your head and your chest up, raise your knee up to 90 degrees and pause.","Return the leg to the starting position."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Hip_Flexion_with_Band/0.webp","assets/exercises/Hip_Flexion_with_Band/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Hip_Flexion_with_Band"},{"id":"Band_Hip_Adductions","name":"Band hip adductions","group":"Bands & kettlebells","type":"Strength","area":"Hips","muscles":["adductors"],"secondary":[],"equipment":["Bands"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":true,"instructions":["Anchor a band around a solid post or other object.","Stand with your left side to the post, and put your right foot through the band, getting it around the ankle.","Stand up straight and hold onto the post if needed. This will be your starting position.","Keeping the knee straight, raise your right legs out to the side as far as you can.","Return to the starting position and repeat for the desired rep count.","Switch sides."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Band_Hip_Adductions/0.webp","assets/exercises/Band_Hip_Adductions/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Band_Hip_Adductions"},{"id":"Goblet_Squat","name":"Goblet squat","group":"Bands & kettlebells","type":"Strength","area":"Legs","muscles":["quadriceps"],"secondary":["calves","glutes","hamstrings","shoulders"],"equipment":["Kettlebell"],"location":"Home & gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Stand with your feet around shoulder-width apart, holding a kettlebell by its horns close to your chest. Choose a light weight while learning the movement.","Brace your trunk, then bend your hips and knees to lower into a squat. Keep your heels grounded and let the knees follow the direction of the toes.","Lower only as far as you can control comfortably. Push through your feet to stand, keeping the weight close and avoiding a bounce at the bottom."],"cues":["Keep your feet planted.","Let knees follow the toes.","Keep the movement controlled."],"images":["assets/exercises/Goblet_Squat/0.webp","assets/exercises/Goblet_Squat/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Goblet_Squat"},{"id":"Kettlebell_One-Legged_Deadlift","name":"Kettlebell one-legged deadlift","group":"Bands & kettlebells","type":"Strength","area":"Legs","muscles":["hamstrings"],"secondary":["glutes","lower back"],"equipment":["Kettlebell"],"location":"Home & gym","level":"Intermediate","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":true,"instructions":["Hold a kettlebell by the handle in one hand. Stand on one leg, on the same side that you hold the kettlebell.","Keeping that knee slightly bent, perform a stiff legged deadlift by bending at the hip, extending your free leg behind you for balance.","Continue lowering the kettlebell until you are parallel to the ground, and then return to the upright position."],"cues":["Send your hips backwards.","Keep the weight close.","Maintain a steady, neutral spine."],"images":["assets/exercises/Kettlebell_One-Legged_Deadlift/0.webp","assets/exercises/Kettlebell_One-Legged_Deadlift/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Kettlebell_One-Legged_Deadlift"},{"id":"One-Arm_Kettlebell_Floor_Press","name":"One-arm kettlebell floor press","group":"Bands & kettlebells","type":"Strength","area":"Chest","muscles":["chest"],"secondary":["triceps"],"equipment":["Kettlebell"],"location":"Home & gym","level":"Intermediate","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":true,"instructions":["Lie on the floor holding a kettlebell with one hand, with your upper arm supported by the floor. The palm should be facing in.","Press the kettlebell straight up toward the ceiling, rotating your wrist.","Lower the kettlebell back to the starting position and repeat."],"cues":["Keep wrists aligned with forearms.","Brace your trunk.","Press smoothly; avoid bouncing."],"images":["assets/exercises/One-Arm_Kettlebell_Floor_Press/0.webp","assets/exercises/One-Arm_Kettlebell_Floor_Press/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/One-Arm_Kettlebell_Floor_Press"},{"id":"Kettlebell_Seated_Press","name":"Kettlebell seated press","group":"Bands & kettlebells","type":"Strength","area":"Shoulders","muscles":["shoulders"],"secondary":["triceps"],"equipment":["Kettlebell","Bench"],"location":"Home & gym","level":"Intermediate","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Sit on the floor and spread your legs out comfortably.","Clean one kettlebell to your shoulder.","Press the kettlebell up and out until it is locked out overhead. Return to the starting position."],"cues":["Keep wrists aligned with forearms.","Brace your trunk.","Press smoothly; avoid bouncing."],"images":["assets/exercises/Kettlebell_Seated_Press/0.webp","assets/exercises/Kettlebell_Seated_Press/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Kettlebell_Seated_Press"},{"id":"Barbell_Squat","name":"Barbell squat","group":"Gym strength","type":"Strength","area":"Legs","muscles":["quadriceps"],"secondary":["calves","glutes","hamstrings","lower back"],"equipment":["Barbell","Rack"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.","Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso.","Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances discussed in the foot stances section).","Begin to slowly lower the bar by bending the knees and hips as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees. Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.","Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.","Repeat for the recommended amount of repetitions."],"cues":["Keep your feet planted.","Let knees follow the toes.","Keep the movement controlled."],"images":["assets/exercises/Barbell_Squat/0.webp","assets/exercises/Barbell_Squat/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Barbell_Squat"},{"id":"Barbell_Bench_Press_-_Medium_Grip","name":"Barbell bench press","group":"Gym strength","type":"Strength","area":"Chest","muscles":["chest"],"secondary":["shoulders","triceps"],"equipment":["Barbell","Bench","Rack"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest.","After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar using your chest muscles. Lock your arms and squeeze your chest in the contracted position at the top of the motion, hold for a second and then start coming down slowly again. Tip: Ideally, lowering the weight should take about twice as long as raising it.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"cues":["Keep wrists aligned with forearms.","Brace your trunk.","Press smoothly; avoid bouncing."],"images":["assets/exercises/Barbell_Bench_Press_-_Medium_Grip/0.webp","assets/exercises/Barbell_Bench_Press_-_Medium_Grip/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Barbell_Bench_Press_-_Medium_Grip"},{"id":"Barbell_Incline_Bench_Press_-_Medium_Grip","name":"Incline barbell bench press","group":"Gym strength","type":"Strength","area":"Chest","muscles":["chest"],"secondary":["shoulders","triceps"],"equipment":["Barbell","Bench","Rack"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Lie back on an incline bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.","As you breathe in, come down slowly until you feel the bar on you upper chest.","After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly again. Tip: it should take at least twice as long to go down than to come up.","Repeat the movement for the prescribed amount of repetitions.","When you are done, place the bar back in the rack."],"cues":["Keep wrists aligned with forearms.","Brace your trunk.","Press smoothly; avoid bouncing."],"images":["assets/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/0.webp","assets/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Barbell_Incline_Bench_Press_-_Medium_Grip"},{"id":"Bent_Over_Barbell_Row","name":"Bent over barbell row","group":"Gym strength","type":"Strength","area":"Back","muscles":["middle back"],"secondary":["biceps","lats","shoulders"],"equipment":["Barbell"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.","Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.","Then inhale and slowly lower the barbell back to the starting position.","Repeat for the recommended amount of repetitions."],"cues":["Keep your torso steady.","Lead with your elbows.","Lower the weight with control."],"images":["assets/exercises/Bent_Over_Barbell_Row/0.webp","assets/exercises/Bent_Over_Barbell_Row/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Bent_Over_Barbell_Row"},{"id":"Romanian_Deadlift","name":"Romanian deadlift","group":"Gym strength","type":"Strength","area":"Legs","muscles":["hamstrings"],"secondary":["calves","glutes","lower back"],"equipment":["Barbell"],"location":"Gym","level":"Intermediate","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion.","Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.","Keeping your back and arms completely straight at all times, use your hips to lift the bar as you exhale. Tip: The movement should not be fast but steady and under control.","Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the knees, unlike when squatting. Tip: Take a deep breath at the start of the movement and keep your chest up. Hold your breath as you lower and exhale as you complete the movement.","Repeat for the recommended amount of repetitions."],"cues":["Send your hips backwards.","Keep the weight close.","Maintain a steady, neutral spine."],"images":["assets/exercises/Romanian_Deadlift/0.webp","assets/exercises/Romanian_Deadlift/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Romanian_Deadlift"},{"id":"Barbell_Deadlift","name":"Barbell deadlift","group":"Gym strength","type":"Strength","area":"Back","muscles":["lower back"],"secondary":["calves","forearms","glutes","hamstrings","lats","middle back","quadriceps","traps"],"equipment":["Barbell"],"location":"Gym","level":"Intermediate","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Stand in front of a loaded barbell.","While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps.","While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright position, stick your chest out and contract the back by bringing the shoulder blades back. Think of how the soldiers in the military look when they are in standing in attention.","Go back to the starting position by bending at the knees while simultaneously leaning the torso forward at the waist while keeping the back straight. When the weights on the bar touch the floor you are back at the starting position and ready to perform another repetition.","Perform the amount of repetitions prescribed in the program."],"cues":["Send your hips backwards.","Keep the weight close.","Maintain a steady, neutral spine."],"images":["assets/exercises/Barbell_Deadlift/0.webp","assets/exercises/Barbell_Deadlift/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Barbell_Deadlift"},{"id":"Trap_Bar_Deadlift","name":"Trap bar deadlift","group":"Gym strength","type":"Strength","area":"Legs","muscles":["quadriceps"],"secondary":["glutes","hamstrings"],"equipment":["Trap bar"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["For this exercise load a trap bar, also known as a hex bar, to an appropriate weight resting on the ground. Stand in the center of the apparatus and grasp both handles.","Lower your hips, look forward with your head and keep your chest up.","Begin the movement by driving through the heels and extend your hips and knees. Avoid rounding your back at all times.","At the completion of the movement, lower the weight back to the ground under control."],"cues":["Send your hips backwards.","Keep the weight close.","Maintain a steady, neutral spine."],"images":["assets/exercises/Trap_Bar_Deadlift/0.webp","assets/exercises/Trap_Bar_Deadlift/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Trap_Bar_Deadlift"},{"id":"Barbell_Curl","name":"Barbell curl","group":"Gym strength","type":"Strength","area":"Arms","muscles":["biceps"],"secondary":["forearms"],"equipment":["Barbell"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position.","While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move.","Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.","Slowly begin to bring the bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"cues":["Keep elbows close to your sides.","Avoid swinging the weight.","Lower slowly and smoothly."],"images":["assets/exercises/Barbell_Curl/0.webp","assets/exercises/Barbell_Curl/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Barbell_Curl"},{"id":"EZ-Bar_Curl","name":"Ez-bar curl","group":"Gym strength","type":"Strength","area":"Arms","muscles":["biceps"],"secondary":[],"equipment":["EZ bar"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Stand up straight while holding an EZ curl bar at the wide outer handle. The palms of your hands should be facing forward and slightly tilted inward due to the shape of the bar. Keep your elbows close to your torso. This will be your starting position.","Now, while keeping your upper arms stationary, exhale and curl the weights forward while contracting the biceps. Focus on only moving your forearms.","Continue to raise the weight until your biceps are fully contracted and the bar is at shoulder level. Hold the top contracted position for a moment and squeeze the biceps.","Then inhale and slowly lower the bar back to the starting position.","Repeat for the recommended amount of repetitions."],"cues":["Keep elbows close to your sides.","Avoid swinging the weight.","Lower slowly and smoothly."],"images":["assets/exercises/EZ-Bar_Curl/0.webp","assets/exercises/EZ-Bar_Curl/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/EZ-Bar_Curl"},{"id":"Barbell_Shrug","name":"Barbell shrug","group":"Gym strength","type":"Strength","area":"Back","muscles":["traps"],"secondary":[],"equipment":["Barbell"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Stand up straight with your feet at shoulder width as you hold a barbell with both hands in front of you using a pronated grip (palms facing the thighs). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for a better grip. This will be your starting position.","Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps.","Slowly return to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Barbell_Shrug/0.webp","assets/exercises/Barbell_Shrug/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Barbell_Shrug"},{"id":"Standing_Military_Press","name":"Standing military press","group":"Gym strength","type":"Strength","area":"Shoulders","muscles":["shoulders"],"secondary":["triceps"],"equipment":["Barbell","Rack"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other.","Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other.","Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position.","Lower the bar down to the collarbone slowly as you inhale.","Lift the bar back up to the starting position as you exhale.","Repeat for the recommended amount of repetitions."],"cues":["Keep wrists aligned with forearms.","Brace your trunk.","Press smoothly; avoid bouncing."],"images":["assets/exercises/Standing_Military_Press/0.webp","assets/exercises/Standing_Military_Press/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Standing_Military_Press"},{"id":"Leg_Press","name":"Leg press","group":"Gym strength","type":"Strength","area":"Legs","muscles":["quadriceps"],"secondary":["calves","glutes","hamstrings"],"equipment":["Machine"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).","Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.","As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.","Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.","Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded."],"cues":["Keep wrists aligned with forearms.","Brace your trunk.","Press smoothly; avoid bouncing."],"images":["assets/exercises/Leg_Press/0.webp","assets/exercises/Leg_Press/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Leg_Press"},{"id":"Leg_Extensions","name":"Leg extensions","group":"Gym strength","type":"Strength","area":"Legs","muscles":["quadriceps"],"secondary":[],"equipment":["Machine"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.","Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.","Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.","Repeat for the recommended amount of times."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Leg_Extensions/0.webp","assets/exercises/Leg_Extensions/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Leg_Extensions"},{"id":"Lying_Leg_Curls","name":"Lying leg curls","group":"Gym strength","type":"Strength","area":"Legs","muscles":["hamstrings"],"secondary":[],"equipment":["Machine"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.","Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.","As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.","As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Lying_Leg_Curls/0.webp","assets/exercises/Lying_Leg_Curls/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Lying_Leg_Curls"},{"id":"Seated_Leg_Curl","name":"Seated leg curl","group":"Gym strength","type":"Strength","area":"Legs","muscles":["hamstrings"],"secondary":[],"equipment":["Machine"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad.","Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position.","As you exhale, pull the machine lever as far as possible to the back of your thighs by flexing at the knees. Keep your torso stationary at all times. Hold the contracted position for a second.","Slowly return to the starting position as you breathe in.","Repeat for the recommended amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Seated_Leg_Curl/0.webp","assets/exercises/Seated_Leg_Curl/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Seated_Leg_Curl"},{"id":"Seated_Calf_Raise","name":"Seated calf raise","group":"Gym strength","type":"Strength","area":"Calves","muscles":["calves"],"secondary":[],"equipment":["Machine"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Sit on the machine and place your toes on the lower portion of the platform provided with the heels extending off. Choose the toe positioning of your choice (forward, in, or out) as per the beginning of this chapter.","Place your lower thighs under the lever pad, which will need to be adjusted according to the height of your thighs. Now place your hands on top of the lever pad in order to prevent it from slipping forward.","Lift the lever slightly by pushing your heels up and release the safety bar. This will be your starting position.","Slowly lower your heels by bending at the ankles until the calves are fully stretched. Inhale as you perform this movement.","Raise the heels by extending the ankles as high as possible as you contract the calves and breathe out. Hold the top contraction for a second.","Repeat for the recommended amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Seated_Calf_Raise/0.webp","assets/exercises/Seated_Calf_Raise/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Seated_Calf_Raise"},{"id":"Thigh_Abductor","name":"Thigh abductor","group":"Gym strength","type":"Strength","area":"Hips","muscles":["abductors"],"secondary":["glutes"],"equipment":["Machine"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.","Slowly press against the machine with your legs to move them away from each other while exhaling.","Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring.","Repeat for the recommended amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Thigh_Abductor/0.webp","assets/exercises/Thigh_Abductor/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Thigh_Abductor"},{"id":"Thigh_Adductor","name":"Thigh adductor","group":"Gym strength","type":"Strength","area":"Hips","muscles":["adductors"],"secondary":["glutes","hamstrings"],"equipment":["Machine"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.","Slowly press against the machine with your legs to move them towards each other while exhaling.","Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary and avoid fast jerking motions in order to prevent any injuries from occurring.","Repeat for the recommended amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Thigh_Adductor/0.webp","assets/exercises/Thigh_Adductor/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Thigh_Adductor"},{"id":"Machine_Bench_Press","name":"Machine bench press","group":"Gym strength","type":"Strength","area":"Chest","muscles":["chest"],"secondary":["shoulders","triceps"],"equipment":["Machine"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Sit down on the Chest Press Machine and select the weight.","Step on the lever provided by the machine since it will help you to bring the handles forward so that you can grab the handles and fully extend the arms.","Grab the handles with a palms-down grip and lift your elbows so that your upper arms are parallel to the floor to the sides of your torso. Tip: Your forearms will be pointing forward since you are grabbing the handles. Once you bring the handles forward and extend the arms you will be at the starting position.","Now bring the handles back towards you as you breathe in.","Push the handles away from you as you flex your pecs and you breathe out. Hold the contraction for a second before going back to the starting position.","Repeat for the recommended amount of reps.","When finished step on the lever again and slowly get the handles back to their original place."],"cues":["Keep wrists aligned with forearms.","Brace your trunk.","Press smoothly; avoid bouncing."],"images":["assets/exercises/Machine_Bench_Press/0.webp","assets/exercises/Machine_Bench_Press/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Machine_Bench_Press"},{"id":"Machine_Shoulder_Military_Press","name":"Machine shoulder press","group":"Gym strength","type":"Strength","area":"Shoulders","muscles":["shoulders"],"secondary":["triceps"],"equipment":["Machine"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Sit down on the Shoulder Press Machine and select the weight.","Grab the handles to your sides as you keep the elbows bent and in line with your torso. This will be your starting position.","Now lift the handles as you exhale and you extend the arms fully. At the top of the position make sure that you hold the contraction for a second.","Lower the handles slowly back to the starting position as you inhale.","Repeat for the recommended amount of repetitions."],"cues":["Keep wrists aligned with forearms.","Brace your trunk.","Press smoothly; avoid bouncing."],"images":["assets/exercises/Machine_Shoulder_Military_Press/0.webp","assets/exercises/Machine_Shoulder_Military_Press/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Machine_Shoulder_Military_Press"},{"id":"Machine_Bicep_Curl","name":"Machine bicep curl","group":"Gym strength","type":"Strength","area":"Arms","muscles":["biceps"],"secondary":[],"equipment":["Machine"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.","Perform the movement by flexing the elbow, pulling your lower arm towards your upper arm.","Pause at the top of the movement, and then slowly return the weight to the starting position.","Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked."],"cues":["Keep elbows close to your sides.","Avoid swinging the weight.","Lower slowly and smoothly."],"images":["assets/exercises/Machine_Bicep_Curl/0.webp","assets/exercises/Machine_Bicep_Curl/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Machine_Bicep_Curl"},{"id":"Machine_Triceps_Extension","name":"Machine triceps extension","group":"Gym strength","type":"Strength","area":"Arms","muscles":["triceps"],"secondary":[],"equipment":["Machine"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position.","Perform the movement by extending the elbow, pulling your lower arm away from your upper arm.","Pause at the completion of the movement, and then slowly return the weight to the starting position.","Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Machine_Triceps_Extension/0.webp","assets/exercises/Machine_Triceps_Extension/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Machine_Triceps_Extension"},{"id":"Reverse_Machine_Flyes","name":"Reverse machine flyes","group":"Gym strength","type":"Strength","area":"Shoulders","muscles":["shoulders"],"secondary":[],"equipment":["Machine"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Adjust the handles so that they are fully to the rear. Make an appropriate weight selection and adjust the seat height so the handles are at shoulder level. Grasp the handles with your hands facing inwards. This will be your starting position.","In a semicircular motion, pull your hands out to your side and back, contracting your rear delts.","Keep your arms slightly bent throughout the movement, with all of the motion occurring at the shoulder joint.","Pause at the rear of the movement, and slowly return the weight to the starting position."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Reverse_Machine_Flyes/0.webp","assets/exercises/Reverse_Machine_Flyes/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Reverse_Machine_Flyes"},{"id":"Seated_Cable_Rows","name":"Seated cable rows","group":"Gym strength","type":"Strength","area":"Back","muscles":["middle back"],"secondary":["biceps","lats","shoulders"],"equipment":["Cable"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.","Lean over as you keep the natural alignment of your back and grab the V-bar handles.","With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.","Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.","Repeat for the recommended amount of repetitions."],"cues":["Keep your torso steady.","Lead with your elbows.","Lower the weight with control."],"images":["assets/exercises/Seated_Cable_Rows/0.webp","assets/exercises/Seated_Cable_Rows/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Seated_Cable_Rows"},{"id":"Wide-Grip_Lat_Pulldown","name":"Wide-grip lat pulldown","group":"Gym strength","type":"Strength","area":"Back","muscles":["lats"],"secondary":["biceps","middle back","shoulders"],"equipment":["Cable"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.","After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.","Repeat this motion for the prescribed amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Wide-Grip_Lat_Pulldown/0.webp","assets/exercises/Wide-Grip_Lat_Pulldown/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Wide-Grip_Lat_Pulldown"},{"id":"Close-Grip_Front_Lat_Pulldown","name":"Close-grip front lat pulldown","group":"Gym strength","type":"Strength","area":"Back","muscles":["lats"],"secondary":["biceps","middle back","shoulders"],"equipment":["Cable"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.","Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.","As you have both arms extended in front of you - while holding the bar at the chosen grip width - bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary (only the arms should move). The forearms should do no other work except for holding the bar; therefore do not try to pull the bar down using the forearms.","After a second in the contracted position, while squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.","6. Repeat this motion for the prescribed amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Close-Grip_Front_Lat_Pulldown/0.webp","assets/exercises/Close-Grip_Front_Lat_Pulldown/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Close-Grip_Front_Lat_Pulldown"},{"id":"Straight-Arm_Pulldown","name":"Straight-arm pulldown","group":"Gym strength","type":"Strength","area":"Back","muscles":["lats"],"secondary":[],"equipment":["Cable"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["You will start by grabbing the wide bar from the top pulley of a pulldown machine and using a wider than shoulder-width pronated (palms down) grip. Step backwards two feet or so.","Bend your torso forward at the waist by around 30-degrees with your arms fully extended in front of you and a slight bend at the elbows. If your arms are not fully extended then you need to step a bit more backwards until they are. Once your arms are fully extended and your torso is slightly bent at the waist, tighten the lats and then you are ready to begin.","While keeping the arms straight, pull the bar down by contracting the lats until your hands are next to the side of the thighs. Breathe out as you perform this step.","While keeping the arms straight, go back to the starting position while breathing in.","Repeat for the recommended amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Straight-Arm_Pulldown/0.webp","assets/exercises/Straight-Arm_Pulldown/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Straight-Arm_Pulldown"},{"id":"Face_Pull","name":"Face pull","group":"Gym strength","type":"Strength","area":"Shoulders","muscles":["shoulders"],"secondary":["middle back"],"equipment":["Cable"],"location":"Gym","level":"Intermediate","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Face_Pull/0.webp","assets/exercises/Face_Pull/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Face_Pull"},{"id":"Cable_Crossover","name":"Cable crossover","group":"Gym strength","type":"Strength","area":"Chest","muscles":["chest"],"secondary":["shoulders"],"equipment":["Cable"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.","Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.","With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms and torso should remain stationary; the movement should only occur at the shoulder joint.","Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.","Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Cable_Crossover/0.webp","assets/exercises/Cable_Crossover/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Cable_Crossover"},{"id":"Triceps_Pushdown","name":"Triceps pushdown","group":"Gym strength","type":"Strength","area":"Arms","muscles":["triceps"],"secondary":[],"equipment":["Cable"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.","Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position.","Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.","After a second hold at the contracted position, bring the bar slowly up to the starting point. Breathe in as you perform this step.","Repeat for the recommended amount of repetitions."],"cues":["Keep wrists aligned with forearms.","Brace your trunk.","Press smoothly; avoid bouncing."],"images":["assets/exercises/Triceps_Pushdown/0.webp","assets/exercises/Triceps_Pushdown/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Triceps_Pushdown"},{"id":"Triceps_Pushdown_-_Rope_Attachment","name":"Triceps pushdown - rope attachment","group":"Gym strength","type":"Strength","area":"Arms","muscles":["triceps"],"secondary":[],"equipment":["Cable"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Attach a rope attachment to a high pulley and grab with a neutral grip (palms facing each other).","Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the rope with the palms facing each other. This is your starting position.","Using the triceps, bring the rope down as you bring each side of the rope to the side of your thighs. At the end of the movement the arms are fully extended and perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.","After holding for a second, at the contracted position, bring the rope slowly up to the starting point. Breathe in as you perform this step.","Repeat for the recommended amount of repetitions."],"cues":["Keep wrists aligned with forearms.","Brace your trunk.","Press smoothly; avoid bouncing."],"images":["assets/exercises/Triceps_Pushdown_-_Rope_Attachment/0.webp","assets/exercises/Triceps_Pushdown_-_Rope_Attachment/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Triceps_Pushdown_-_Rope_Attachment"},{"id":"Cable_Rope_Overhead_Triceps_Extension","name":"Cable rope overhead triceps extension","group":"Gym strength","type":"Strength","area":"Arms","muscles":["triceps"],"secondary":[],"equipment":["Cable"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Attach a rope to the bottom pulley of the pulley machine.","Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position.","Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.","Return to the starting position by flexing your triceps as you breathe out.","Repeat for the recommended amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Cable_Rope_Overhead_Triceps_Extension/0.webp","assets/exercises/Cable_Rope_Overhead_Triceps_Extension/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Cable_Rope_Overhead_Triceps_Extension"},{"id":"Standing_Biceps_Cable_Curl","name":"Standing biceps cable curl","group":"Gym strength","type":"Strength","area":"Arms","muscles":["biceps"],"secondary":[],"equipment":["Cable"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Stand up with your torso upright while holding a cable curl bar that is attached to a low pulley. Grab the cable bar at shoulder width and keep the elbows close to the torso. The palm of your hands should be facing up (supinated grip). This will be your starting position.","While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.","Slowly begin to bring the curl bar back to starting position as your breathe in.","Repeat for the recommended amount of repetitions."],"cues":["Keep elbows close to your sides.","Avoid swinging the weight.","Lower slowly and smoothly."],"images":["assets/exercises/Standing_Biceps_Cable_Curl/0.webp","assets/exercises/Standing_Biceps_Cable_Curl/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Standing_Biceps_Cable_Curl"},{"id":"Pallof_Press","name":"Pallof press","group":"Gym strength","type":"Strength","area":"Core","muscles":["abdominals"],"secondary":["chest","shoulders","triceps"],"equipment":["Cable"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":true,"instructions":["Connect a standard handle to a tower, and—if possible—position the cable to shoulder height. If not, a low pulley will suffice.","With your side to the cable, grab the handle with both hands and step away from the tower. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable.","With your feet positioned hip-width apart and knees slightly bent, hold the cable to the middle of your chest. This will be your starting position.","Press the cable away from your chest, fully extending both arms. You core should be tight and engaged.","Hold the repetition for several seconds before returning to the starting position.","At the conclusion of the set, repeat facing the other direction."],"cues":["Keep wrists aligned with forearms.","Brace your trunk.","Press smoothly; avoid bouncing."],"images":["assets/exercises/Pallof_Press/0.webp","assets/exercises/Pallof_Press/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Pallof_Press"},{"id":"Cable_Crunch","name":"Cable crunch","group":"Gym strength","type":"Strength","area":"Core","muscles":["abdominals"],"secondary":[],"equipment":["Cable"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Kneel below a high pulley that contains a rope attachment.","Grasp cable rope attachment and lower the rope until your hands are placed next to your face.","Flex your hips slightly and allow the weight to hyperextend the lower back. This will be your starting position.","With the hips stationary, flex the waist as you contract the abs so that the elbows travel towards the middle of the thighs. Exhale as you perform this portion of the movement and hold the contraction for a second.","Slowly return to the starting position as you inhale. Tip: Make sure that you keep constant tension on the abs throughout the movement. Also, do not choose a weight so heavy that the lower back handles the brunt of the work.","Repeat for the recommended amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Cable_Crunch/0.webp","assets/exercises/Cable_Crunch/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Cable_Crunch"},{"id":"Pull_Through","name":"Pull through","group":"Gym strength","type":"Strength","area":"Glutes","muscles":["glutes"],"secondary":["hamstrings","lower back"],"equipment":["Cable"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Begin standing a few feet in front of a low pulley with a rope or handle attached. Face away from the machine, straddling the cable, with your feet set wide apart.","Begin the movement by reaching through your legs as far as possible, bending at the hips. Keep your knees slightly bent. Keeping your arms straight, extend through the hip to stand straight up. Avoid pulling upward through the shoulders; all of the motion should originate through the hips."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Pull_Through/0.webp","assets/exercises/Pull_Through/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Pull_Through"},{"id":"Pullups","name":"Pullups","group":"Gym strength","type":"Strength","area":"Back","muscles":["lats"],"secondary":["biceps","middle back"],"equipment":["Pull-up bar"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.","Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.","After a second on the contracted position, start to inhale and slowly lower your torso back to the starting position when your arms are fully extended and the lats are fully stretched.","Repeat this motion for the prescribed amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Pullups/0.webp","assets/exercises/Pullups/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Pullups"},{"id":"Chin-Up","name":"Chin-up","group":"Gym strength","type":"Strength","area":"Back","muscles":["lats"],"secondary":["biceps","forearms","middle back"],"equipment":["Pull-up bar"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width.","As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement.","As you breathe out, pull your torso up until your head is around the level of the pull-up bar. Concentrate on using the biceps muscles in order to perform the movement. Keep the elbows close to your body. Tip: The upper torso should remain stationary as it moves through space and only the arms should move. The forearms should do no other work other than hold the bar.","After a second of squeezing the biceps in the contracted position, slowly lower your torso back to the starting position; when your arms are fully extended. Breathe in as you perform this portion of the movement.","Repeat this motion for the prescribed amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Chin-Up/0.webp","assets/exercises/Chin-Up/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Chin-Up"},{"id":"Inverted_Row","name":"Inverted row","group":"Gym strength","type":"Strength","area":"Back","muscles":["middle back"],"secondary":["lats"],"equipment":["Pull-up bar"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Position a bar in a rack to about waist height. You can also use a smith machine.","Take a wider than shoulder width grip on the bar and position yourself hanging underneath the bar. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position.","Begin by flexing the elbow, pulling your chest towards the bar. Retract your shoulder blades as you perform the movement.","Pause at the top of the motion, and return yourself to the start position.","Repeat for the desired number of repetitions."],"cues":["Keep your torso steady.","Lead with your elbows.","Lower the weight with control."],"images":["assets/exercises/Inverted_Row/0.webp","assets/exercises/Inverted_Row/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Inverted_Row"},{"id":"Arm_Circles","name":"Arm circles","group":"Mobility & stretching","type":"Mobility","area":"Shoulders","muscles":["shoulders"],"secondary":["traps"],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":false,"instructions":["Stand up and extend your arms straight out by the sides. The arms should be parallel to the floor and perpendicular (90-degree angle) to your torso. This will be your starting position.","Slowly start to make circles of about 1 foot in diameter with each outstretched arm. Breathe normally as you perform the movement.","Continue the circular motion of the outstretched arms for about ten seconds. Then reverse the movement, going the opposite direction."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Arm_Circles/0.webp","assets/exercises/Arm_Circles/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Arm_Circles"},{"id":"Shoulder_Circles","name":"Shoulder circles","group":"Mobility & stretching","type":"Mobility","area":"Shoulders","muscles":["shoulders"],"secondary":["traps"],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":false,"instructions":["With shoulders relaxed and arms resting loosely at your sides (or in your lap if you're seated), gently roll your shoulders forward, up, back, and down.","Reverse direction. You can do this exercise alternating shoulders or both at the same time."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Shoulder_Circles/0.webp","assets/exercises/Shoulder_Circles/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Shoulder_Circles"},{"id":"Ankle_Circles","name":"Ankle circles","group":"Mobility & stretching","type":"Mobility","area":"Calves","muscles":["calves"],"secondary":[],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":false,"instructions":["Use a sturdy object like a squat rack to hold yourself.","Lift the right leg in the air (just around 2 inches from the floor) and perform a circular motion with the big toe. Pretend that you are drawing a big circle with it. Tip: One circle equals 1 repetition. Breathe normally as you perform the movement.","When you are done with the right foot, then repeat with the left leg."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Ankle_Circles/0.webp","assets/exercises/Ankle_Circles/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Ankle_Circles"},{"id":"Hip_Circles_prone","name":"Hip circles (prone)","group":"Mobility & stretching","type":"Mobility","area":"Hips","muscles":["abductors"],"secondary":["adductors"],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":false,"instructions":["Position yourself on your hands and knees on the ground. Maintaining good posture, raise one bent knee off of the ground. This will be your starting position.","Keeping the knee in a bent position, rotate the femur in an arc, attempting to make a big circle with your knee.","Perform this slowly for a number of repetitions, and repeat on the other side."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Hip_Circles_prone/0.webp","assets/exercises/Hip_Circles_prone/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Hip_Circles_prone"},{"id":"Standing_Hip_Circles","name":"Standing hip circles","group":"Mobility & stretching","type":"Mobility","area":"Hips","muscles":["abductors"],"secondary":["adductors"],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":false,"instructions":["Begin standing on one leg, holding to a vertical support.","Raise the unsupported knee to 90 degrees. This will be your starting position.","Open the hip as far as possible, attempting to make a big circle with your knee.","Perform this movement slowly for a number of repetitions, and repeat on the other side."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Standing_Hip_Circles/0.webp","assets/exercises/Standing_Hip_Circles/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Standing_Hip_Circles"},{"id":"Cat_Stretch","name":"Cat stretch","group":"Mobility & stretching","type":"Mobility","area":"Back","muscles":["lower back"],"secondary":["middle back","traps"],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":false,"instructions":["Position yourself on the floor on your hands and knees.","Pull your belly in and round your spine, lower back, shoulders, and neck, letting your head drop.","Hold for 15 seconds."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Cat_Stretch/0.webp","assets/exercises/Cat_Stretch/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Cat_Stretch"},{"id":"Dynamic_Chest_Stretch","name":"Dynamic chest stretch","group":"Mobility & stretching","type":"Mobility","area":"Chest","muscles":["chest"],"secondary":["middle back"],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":false,"instructions":["Stand with your hands together, arms extended directly in front of you. This will be your starting position.","Keeping your arms straight, quickly move your arms back as far as possible and back in again, similar to an exaggerated clapping motion. Repeat 5-10 times, increasing speed as you do so."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Dynamic_Chest_Stretch/0.webp","assets/exercises/Dynamic_Chest_Stretch/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Dynamic_Chest_Stretch"},{"id":"Dynamic_Back_Stretch","name":"Dynamic back stretch","group":"Mobility & stretching","type":"Mobility","area":"Back","muscles":["lats"],"secondary":[],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":false,"instructions":["Stand with your feet shoulder width apart. This will be your starting position.","Keeping your arms straight, swing them straight up in front of you 5-10 times, increasing the range of motion each time until your arms are above your head."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Dynamic_Back_Stretch/0.webp","assets/exercises/Dynamic_Back_Stretch/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Dynamic_Back_Stretch"},{"id":"Standing_Lateral_Stretch","name":"Standing side reach","group":"Mobility & stretching","type":"Stretch","area":"Core","muscles":["abdominals"],"secondary":[],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":true,"instructions":["Take a slightly wider than hip distance stance with your knees slightly bent.","Place your right hand on your right hip to support the spine.","Raise your left arm in a vertical line and place your left hand behind your head. Keep it there as you incline your torso to the right.","Keep your weight evenly distributed between both legs (don't lean into your left hip). Switch sides."],"cues":["Ease into gentle tension.","Breathe slowly; do not bounce.","Stay within a comfortable range."],"images":["assets/exercises/Standing_Lateral_Stretch/0.webp","assets/exercises/Standing_Lateral_Stretch/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Standing_Lateral_Stretch"},{"id":"Childs_Pose","name":"Child’s pose","group":"Mobility & stretching","type":"Stretch","area":"Back","muscles":["lower back"],"secondary":["glutes","middle back"],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":false,"instructions":["Get on your hands and knees, walk your hands in front of you.","Lower your buttocks down to sit on your heels. Let your arms drag along the floor as you sit back to stretch your entire spine.","Once you settle onto your heels, bring your hands next to your feet and relax. \"breathe\" into your back. Rest your forehead on the floor. Avoid this position if you have knee problems."],"cues":["Ease into gentle tension.","Breathe slowly; do not bounce.","Stay within a comfortable range."],"images":["assets/exercises/Childs_Pose/0.webp","assets/exercises/Childs_Pose/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Childs_Pose"},{"id":"Kneeling_Hip_Flexor","name":"Kneeling hip flexor","group":"Mobility & stretching","type":"Stretch","area":"Legs","muscles":["quadriceps"],"secondary":["quadriceps"],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":true,"instructions":["Kneel on a mat and bring your right knee up so the bottom of your foot is on the floor and extend your left leg out behind you so the top of your foot is on the floor.","Shift your weight forward until you feel a stretch in your hip. Hold for 15 seconds, then repeat for your other side."],"cues":["Ease into gentle tension.","Breathe slowly; do not bounce.","Stay within a comfortable range."],"images":["assets/exercises/Kneeling_Hip_Flexor/0.webp","assets/exercises/Kneeling_Hip_Flexor/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Kneeling_Hip_Flexor"},{"id":"Calf_Stretch_Hands_Against_Wall","name":"Wall calf stretch","group":"Mobility & stretching","type":"Stretch","area":"Calves","muscles":["calves"],"secondary":[],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":true,"instructions":["Stand facing a wall from several feet away. Stagger your stance, placing one foot forward.","Lean forward and rest your hands on the wall, keeping your heel, hip and head in a straight line.","Attempt to keep your heel on the ground. Hold for 10-20 seconds and then switch sides."],"cues":["Ease into gentle tension.","Breathe slowly; do not bounce.","Stay within a comfortable range."],"images":["assets/exercises/Calf_Stretch_Hands_Against_Wall/0.webp","assets/exercises/Calf_Stretch_Hands_Against_Wall/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Calf_Stretch_Hands_Against_Wall"},{"id":"Standing_Soleus_And_Achilles_Stretch","name":"Standing soleus and achilles stretch","group":"Mobility & stretching","type":"Stretch","area":"Calves","muscles":["calves"],"secondary":[],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":true,"instructions":["Stand with your feet hip-distance apart, one foot slightly in front of the other.","Bend both knees, keeping your back heel on the floor. Switch sides."],"cues":["Ease into gentle tension.","Breathe slowly; do not bounce.","Stay within a comfortable range."],"images":["assets/exercises/Standing_Soleus_And_Achilles_Stretch/0.webp","assets/exercises/Standing_Soleus_And_Achilles_Stretch/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Standing_Soleus_And_Achilles_Stretch"},{"id":"Seated_Floor_Hamstring_Stretch","name":"Seated floor hamstring stretch","group":"Mobility & stretching","type":"Stretch","area":"Legs","muscles":["hamstrings"],"secondary":["calves"],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":false,"instructions":["Sit on a mat with your right leg extended in front of you and your left leg bent with your foot against your right inner thigh.","Lean forward from your hips and reach for your ankle until you feel a stretch in your hamstring. Hold for 15 seconds, then repeat for your other side."],"cues":["Ease into gentle tension.","Breathe slowly; do not bounce.","Stay within a comfortable range."],"images":["assets/exercises/Seated_Floor_Hamstring_Stretch/0.webp","assets/exercises/Seated_Floor_Hamstring_Stretch/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Seated_Floor_Hamstring_Stretch"},{"id":"Hamstring_Stretch","name":"Hamstring stretch","group":"Mobility & stretching","type":"Stretch","area":"Legs","muscles":["hamstrings"],"secondary":[],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":false,"instructions":["Lie on your back with one leg extended above you, with the hip at ninety degrees. Keep the other leg flat on the floor.","Loop a belt, band, or rope over the ball of your foot. This will be your starting position.","Pull on the belt to create tension in the calves and hamstrings. Hold this stretch for 10-30 seconds, and repeat with the other leg."],"cues":["Ease into gentle tension.","Breathe slowly; do not bounce.","Stay within a comfortable range."],"images":["assets/exercises/Hamstring_Stretch/0.webp","assets/exercises/Hamstring_Stretch/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Hamstring_Stretch"},{"id":"On_Your_Side_Quad_Stretch","name":"Side-lying quad stretch","group":"Mobility & stretching","type":"Stretch","area":"Legs","muscles":["quadriceps"],"secondary":[],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":true,"instructions":["Start off by lying on your right side, with your right knee bent at a 90-degree angle resting on the floor in front of you (this stabilizes the torso).","Bend your left knee behind you and hold your left foot with your left hand. To stretch your hip flexor, press your left hip forward as you push your left foot back into your hand. Switch sides."],"cues":["Ease into gentle tension.","Breathe slowly; do not bounce.","Stay within a comfortable range."],"images":["assets/exercises/On_Your_Side_Quad_Stretch/0.webp","assets/exercises/On_Your_Side_Quad_Stretch/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/On_Your_Side_Quad_Stretch"},{"id":"Shoulder_Stretch","name":"Shoulder stretch","group":"Mobility & stretching","type":"Stretch","area":"Shoulders","muscles":["shoulders"],"secondary":[],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":true,"instructions":["Reach your left arm across your body and hold it straight."],"cues":["Ease into gentle tension.","Breathe slowly; do not bounce.","Stay within a comfortable range."],"images":["assets/exercises/Shoulder_Stretch/0.webp","assets/exercises/Shoulder_Stretch/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Shoulder_Stretch"},{"id":"Triceps_Stretch","name":"Triceps stretch","group":"Mobility & stretching","type":"Stretch","area":"Arms","muscles":["triceps"],"secondary":["lats"],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":true,"instructions":["Reach your hand behind your head, grasp your elbow and gently pull. Hold for 10 to 20 seconds, then switch sides."],"cues":["Ease into gentle tension.","Breathe slowly; do not bounce.","Stay within a comfortable range."],"images":["assets/exercises/Triceps_Stretch/0.webp","assets/exercises/Triceps_Stretch/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Triceps_Stretch"},{"id":"Side_Neck_Stretch","name":"Side neck stretch","group":"Mobility & stretching","type":"Stretch","area":"Neck","muscles":["neck"],"secondary":[],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":true,"instructions":["Start with your shoulders relaxed, gently tilt your head towards your shoulder.","Assist stretch with a gentle pull on the side of the head."],"cues":["Ease into gentle tension.","Breathe slowly; do not bounce.","Stay within a comfortable range."],"images":["assets/exercises/Side_Neck_Stretch/0.webp","assets/exercises/Side_Neck_Stretch/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Side_Neck_Stretch"},{"id":"One_Knee_To_Chest","name":"One knee to chest","group":"Mobility & stretching","type":"Stretch","area":"Glutes","muscles":["glutes"],"secondary":["hamstrings","lower back"],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":true,"instructions":["Start off by lying on the floor.","Extend one leg straight and pull the other knee to your chest. Hold under the knee joint to protect the kneecap.","Gently tug that knee toward your nose.","Switch sides. This stretches the buttocks and lower back of the bent leg and the hip flexor of the straight leg."],"cues":["Ease into gentle tension.","Breathe slowly; do not bounce.","Stay within a comfortable range."],"images":["assets/exercises/One_Knee_To_Chest/0.webp","assets/exercises/One_Knee_To_Chest/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/One_Knee_To_Chest"},{"id":"Knee_Across_The_Body","name":"Knee across the body","group":"Mobility & stretching","type":"Stretch","area":"Glutes","muscles":["glutes"],"secondary":["abductors","lower back"],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":true,"instructions":["Lie down on the floor with your right leg straight. Bend your left leg and lower it across your body, holding the knee down toward the floor with your right hand. (The knee doesn't need to touch the floor if you're tight.)","Place your left arm comfortably beside you and turn your head to the left. Imagine you have a weight tied to your tailbone. let your tailbone fall back toward the floor as your chest reaches in the opposite direction to stretch your lower back. Switch sides."],"cues":["Ease into gentle tension.","Breathe slowly; do not bounce.","Stay within a comfortable range."],"images":["assets/exercises/Knee_Across_The_Body/0.webp","assets/exercises/Knee_Across_The_Body/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Knee_Across_The_Body"},{"id":"Ankle_On_The_Knee","name":"Seated figure-four stretch","group":"Mobility & stretching","type":"Stretch","area":"Glutes","muscles":["glutes"],"secondary":[],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":true,"instructions":["From a lying position, bend your knees and keep your feet on the floor.","Place your ankle of one foot on your opposite knee.","Grasp the thigh or knee of the bottom leg and pull both of your legs into the chest. Relax your neck and shoulders. Hold for 10-20 seconds and then switch sides."],"cues":["Ease into gentle tension.","Breathe slowly; do not bounce.","Stay within a comfortable range."],"images":["assets/exercises/Ankle_On_The_Knee/0.webp","assets/exercises/Ankle_On_The_Knee/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Ankle_On_The_Knee"},{"id":"Butterfly","name":"Butterfly","group":"Mobility & stretching","type":"Strength","area":"Chest","muscles":["chest"],"secondary":[],"equipment":["Machine"],"location":"Gym","level":"Beginner","mode":"reps","seconds":30,"reps":10,"sets":3,"rest":60,"unilateral":false,"instructions":["Sit on the machine with your back flat on the pad.","Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position.","Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.","Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.","Repeat for the recommended amount of repetitions."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Butterfly/0.webp","assets/exercises/Butterfly/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Butterfly"},{"id":"Seated_Overhead_Stretch","name":"Seated overhead stretch","group":"Mobility & stretching","type":"Stretch","area":"Core","muscles":["abdominals"],"secondary":[],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":false,"instructions":["Sit up straight on an exercise mat.","Touch the soles of your feet together with your feet six to eight inches in front of your hips.","Place one hand on the floor beside you and your other hand behind your head.","Lift your elbow to the ceiling as you incline your torso to the other side. Hold for 10 to 20 seconds, then switch sides."],"cues":["Ease into gentle tension.","Breathe slowly; do not bounce.","Stay within a comfortable range."],"images":["assets/exercises/Seated_Overhead_Stretch/0.webp","assets/exercises/Seated_Overhead_Stretch/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Seated_Overhead_Stretch"},{"id":"Kneeling_Forearm_Stretch","name":"Kneeling forearm stretch","group":"Mobility & stretching","type":"Stretch","area":"Arms","muscles":["forearms"],"secondary":[],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":false,"instructions":["Start by kneeling on a mat with your palms flat and your fingers pointing back toward your knees.","Slowly lean back keeping your palms flat on the floor until you feel a stretch in your wrists and forearms. Hold for 20-30 seconds."],"cues":["Ease into gentle tension.","Breathe slowly; do not bounce.","Stay within a comfortable range."],"images":["assets/exercises/Kneeling_Forearm_Stretch/0.webp","assets/exercises/Kneeling_Forearm_Stretch/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Kneeling_Forearm_Stretch"},{"id":"Upper_Back_Stretch","name":"Upper back stretch","group":"Mobility & stretching","type":"Stretch","area":"Back","muscles":["middle back"],"secondary":["middle back"],"equipment":["Bodyweight"],"location":"Home & gym","level":"Beginner","mode":"time","seconds":30,"reps":10,"sets":1,"rest":10,"unilateral":false,"instructions":["Clasp fingers together with your thumbs pointing down, round your shoulders as you reach your hands forward."],"cues":["Ease into gentle tension.","Breathe slowly; do not bounce.","Stay within a comfortable range."],"images":["assets/exercises/Upper_Back_Stretch/0.webp","assets/exercises/Upper_Back_Stretch/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Upper_Back_Stretch"},{"id":"Bicycling_Stationary","name":"Exercise bike","group":"Conditioning","type":"Conditioning","area":"Legs","muscles":["quadriceps"],"secondary":["calves","glutes","hamstrings"],"equipment":["Cardio machine"],"location":"Gym","level":"Beginner","mode":"time","seconds":180,"reps":10,"sets":1,"rest":10,"unilateral":false,"instructions":["To begin, seat yourself on the bike and adjust the seat to your height.","Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Bicycling_Stationary/0.webp","assets/exercises/Bicycling_Stationary/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Bicycling_Stationary"},{"id":"Walking_Treadmill","name":"Treadmill walk","group":"Conditioning","type":"Conditioning","area":"Legs","muscles":["quadriceps"],"secondary":["calves","glutes","hamstrings"],"equipment":["Cardio machine"],"location":"Gym","level":"Beginner","mode":"time","seconds":180,"reps":10,"sets":1,"rest":10,"unilateral":false,"instructions":["To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.","Treadmills offer convenience, cardiovascular benefits, and usually have less impact than walking outside. When walking, you should move at a moderate to fast pace, not a leisurely one. Being an activity of lower intensity, walking doesn't burn as many calories as some other activities, but still provides great benefit. A 150 lb person will burn about 175 calories walking 4 miles per hour for 30 minutes, compared to 450 calories running twice as fast. Maintain proper posture as you walk, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Walking_Treadmill/0.webp","assets/exercises/Walking_Treadmill/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Walking_Treadmill"},{"id":"Jogging_Treadmill","name":"Treadmill jog","group":"Conditioning","type":"Conditioning","area":"Legs","muscles":["quadriceps"],"secondary":["glutes","hamstrings"],"equipment":["Cardio machine"],"location":"Gym","level":"Beginner","mode":"time","seconds":180,"reps":10,"sets":1,"rest":10,"unilateral":false,"instructions":["To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.","Treadmills offer convenience, cardiovascular benefits, and usually have less impact than jogging outside. A 150 lb person will burn almost 250 calories jogging for 30 minutes, compared to more than 450 calories running. Maintain proper posture as you jog, and only hold onto the handles when necessary, such as when dismounting or checking your heart rate."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Jogging_Treadmill/0.webp","assets/exercises/Jogging_Treadmill/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Jogging_Treadmill"},{"id":"Elliptical_Trainer","name":"Elliptical trainer","group":"Conditioning","type":"Conditioning","area":"Legs","muscles":["quadriceps"],"secondary":["calves","glutes","hamstrings"],"equipment":["Cardio machine"],"location":"Gym","level":"Intermediate","mode":"time","seconds":180,"reps":10,"sets":1,"rest":10,"unilateral":false,"instructions":["To begin, step onto the elliptical and select the desired option from the menu. Most ellipticals have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout.","The handles can be used to monitor your heart rate to help you stay at an appropriate intensity."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Elliptical_Trainer/0.webp","assets/exercises/Elliptical_Trainer/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Elliptical_Trainer"},{"id":"Rowing_Stationary","name":"Rowing machine","group":"Conditioning","type":"Conditioning","area":"Legs","muscles":["quadriceps"],"secondary":["biceps","calves","glutes","hamstrings","lower back","middle back"],"equipment":["Cardio machine"],"location":"Gym","level":"Intermediate","mode":"time","seconds":180,"reps":10,"sets":1,"rest":10,"unilateral":false,"instructions":["To begin, seat yourself on the rower. Make sure that your heels are resting comfortably against the base of the foot pedals and that the straps are secured. Select the program that you wish to use, if applicable. Sit up straight and bend forward at the hips.","There are three phases of movement when using a rower. The first phase is when you come forward on the rower. Your knees are bent and against your chest. Your upper body is leaning slightly forward while still maintaining good posture. Next, push against the foot pedals and extend your legs while bringing your hands to your upper abdominal area, squeezing your shoulders back as you do so. To avoid straining your back, use primarily your leg and hip muscles.","The recovery phase simply involves straightening your arms, bending the knees, and bringing your body forward again as you transition back into the first phase."],"cues":["Keep your torso steady.","Lead with your elbows.","Lower the weight with control."],"images":["assets/exercises/Rowing_Stationary/0.webp","assets/exercises/Rowing_Stationary/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Rowing_Stationary"},{"id":"Recumbent_Bike","name":"Recumbent bike","group":"Conditioning","type":"Conditioning","area":"Legs","muscles":["quadriceps"],"secondary":["calves","glutes","hamstrings"],"equipment":["Cardio machine"],"location":"Gym","level":"Beginner","mode":"time","seconds":180,"reps":10,"sets":1,"rest":10,"unilateral":false,"instructions":["To begin, seat yourself on the bike and adjust the seat to your height.","Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.","Recumbent bikes offer convenience, cardiovascular benefits, and have less impact than other activities. A 150 lb person will burn about 230 calories cycling at a moderate rate for 30 minutes, compared to 450 calories or more running."],"cues":["Move with control.","Keep breathing throughout.","Use a comfortable range."],"images":["assets/exercises/Recumbent_Bike/0.webp","assets/exercises/Recumbent_Bike/1.webp"],"source":"https://github.com/yuhonas/free-exercise-db/tree/main/exercises/Recumbent_Bike"}];
